 "aws_medialive_channel": {
  "body": "  name          = \"main-channel\"\n  channel_class = \"STANDARD\"\n  role_arn      = aws_iam_role.medialive.arn\n\n  input_specification {\n    codec            = \"AVC\"\n    input_resolution = \"HD\"\n    maximum_bitrate  = \"MAX_20_MBPS\"\n  }\n\n  input_attachments {\n    input_attachment_name = \"stadium\"\n    input_id              = aws_medialive_input.contribution.id\n  }\n\n  destinations {\n    id = \"mediapackage\"\n\n    media_package_settings {\n      channel_id = aws_media_package_channel.live.id\n    }\n  }\n\n  encoder_settings {\n    timecode_config {\n      source = \"EMBEDDED\"\n    }\n\n    audio_descriptions {\n      audio_selector_name = \"default\"\n      name                = \"audio-1\"\n    }\n\n    video_descriptions {\n      name   = \"video-1080p\"\n      width  = 1920\n      height = 1080\n    }\n\n    output_groups {\n      output_group_settings {\n        media_package_group_settings {\n          destination {\n            destination_ref_id = \"mediapackage\"\n          }\n        }\n      }\n\n      outputs {\n        output_name             = \"1080p\"\n        audio_description_names = [\"audio-1\"]\n        video_description_name  = \"video-1080p\"\n\n        output_settings {\n          media_package_output_settings {}\n        }\n      }\n    }\n  }",
  "from": "reference architecture architectures/11-media-streaming"
 },
