 "azurerm_container_app": {
  "body": "  name                         = \"ca-orders\"\n  resource_group_name           = azurerm_resource_group.main.name\n  container_app_environment_id  = azurerm_container_app_environment.main.id\n  revision_mode                 = \"Single\"\n\n  identity {\n    type         = \"UserAssigned\"\n    identity_ids = [azurerm_user_assigned_identity.orders.id]\n  }\n\n  registry {\n    server   = azurerm_container_registry.main.login_server\n    identity = azurerm_user_assigned_identity.orders.id\n  }\n\n  template {\n    min_replicas = 2\n    max_replicas = 20\n\n    container {\n      name   = \"orders\"\n      image  = \"${azurerm_container_registry.main.login_server}/orders:1.4.2\"\n      cpu    = 0.5\n      memory = \"1Gi\"\n\n      liveness_probe {\n        transport = \"HTTP\"\n        path      = \"/healthz\"\n        port      = 8080\n      }\n\n      env {\n        name  = \"SERVICEBUS_NAMESPACE\"\n        value = azurerm_servicebus_namespace.main.name\n      }\n    }\n\n    custom_scale_rule {\n      name             = \"servicebus-queue-length\"\n      custom_rule_type = \"azure-servicebus\"\n\n      metadata = {\n        queueName    = azurerm_servicebus_queue.shipping.name\n        messageCount = \"20\"\n      }\n\n      authentication {\n        secret_name       = \"servicebus-connection\"\n        trigger_parameter = \"connection\"\n      }\n    }\n  }\n\n  ingress {\n    external_enabled = false\n    target_port      = 8080\n\n    traffic_weight {\n      percentage      = 100\n      latest_revision = true\n    }\n  }",
  "from": "reference architecture architectures-azure/04-container-apps-microservices"
 },
