  "body": "  name                = \"security-alerts\"\n  resource_group_name  = azurerm_resource_group.main.name\n  short_name           = \"secalerts\"\n\n  email_receiver {\n    name          = \"security-team\"\n    email_address = \"security@example.com\"\n  }",
