 "azurerm_monitor_autoscale_setting": {
  "body": "  name                = \"autoscale-app\"\n  resource_group_name  = azurerm_resource_group.main.name\n  location             = azurerm_resource_group.main.location\n  target_resource_id   = azurerm_linux_virtual_machine_scale_set.app.id\n\n  profile {\n    name = \"default\"\n\n    capacity {\n      default = 3\n      minimum = 3\n      maximum = 10\n    }\n\n    rule {\n      metric_trigger {\n        metric_name        = \"Percentage CPU\"\n        metric_resource_id = azurerm_linux_virtual_machine_scale_set.app.id\n        time_grain          = \"PT1M\"\n        statistic            = \"Average\"\n        time_window          = \"PT5M\"\n        time_aggregation      = \"Average\"\n        operator              = \"GreaterThan\"\n        threshold             = 65\n      }\n\n      scale_action {\n        direction = \"Increase\"\n        type      = \"ChangeCount\"\n        value     = \"2\"\n        cooldown  = \"PT5M\"\n      }\n    }\n  }",
  "from": "reference architecture architectures-azure/01-three-tier-web-app"
 },
