 "azurerm_stream_analytics_job": {
  "body": "    name                = \"sa-telemetry-aggregate\"\n    resource_group_name  = azurerm_resource_group.main.name\n    location             = azurerm_resource_group.main.location\n\n    streaming_units                     = 6\n    compatibility_level                 = \"1.2\"\n    events_late_arrival_max_delay_in_seconds = 60\n    events_out_of_order_max_delay_in_seconds = 50\n    events_out_of_order_policy           = \"Adjust\"\n    output_error_policy                  = \"Drop\"\n\n    identity {\n      type = \"SystemAssigned\"\n    }\n\n    transformation_query = <<QUERY\n  SELECT device_id, AVG(temperature) AS avg_temperature\n  INTO [cosmos-output]\n  FROM [telemetry-input] TIMESTAMP BY event_time\n  GROUP BY device_id, TumblingWindow(minute, 1)\n  QUERY",
  "from": "reference architecture architectures-azure/07-streaming-realtime"
 },
