  "body": "  billing_account = \"012345-6789AB-CDEF01\"\n  display_name    = \"monthly-governance-budget\"\n\n  budget_filter {\n    projects = [\"projects/example-project\"]\n  }\n\n  amount {\n    specified_amount {\n      currency_code = \"USD\"\n      units         = \"10000\"\n    }\n  }\n\n  threshold_rules {\n    threshold_percent = 0.9\n  }",
