  "body": "  compartment_id                   = var.compartment_id\n  display_name                     = \"deferred-work\"\n  retention_in_seconds             = 86400\n  visibility_in_seconds            = 60\n  dead_letter_queue_delivery_count = 5\n  custom_encryption_key_id         = oci_kms_key.data.id",
