  "body": "  compartment_id = var.compartment_id\n  display_name   = \"clickstream-to-enrich\"\n\n  source {\n    kind      = \"streaming\"\n    stream_id = oci_streaming_stream.clickstream.id\n\n    cursor {\n      kind = \"LATEST\"\n    }\n  }\n\n  target {\n    kind              = \"functions\"\n    function_id       = oci_functions_function.enrich.id\n    batch_size_in_num = 100\n    batch_time_in_sec = 5\n  }",
